BOOL __fastcall SKILLMONST_SrvStFn52_Emerge(::SGAMEDATA * pGame, D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    if (!pUnit) {
      return 1;
    }

    pUnit->eUnitFlags |= UNITFLAG_ISVALIDTARGET | UNITFLAG_CANBEATTACKED | UNITFLAG_TARGETABLE;
    return 1;
}

BOOL __fastcall SKILLMONST_SrvStFn53_MonInferno(::SGAMEDATA * pGame, D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillsTxtBase = sgptDataTable->pTxtSkills;
    if (!(pSkillsTxtBase + eSkill)) {
      return 0;
    }

    D2SkillStrc* pSkill = D2Common::Units::GetCurrentSkill(pUnit);
    if (!pSkill) {
      return 0;
    }

    int nDuration = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillsTxtBase[eSkill].calc[1], eSkill, nSkillLvl);
    if (nDuration < 1) {
      nDuration = 1;
    }

    D2Common::Skills::SKILL_SetParam1(pSkill, pGame->dwGameFrame + nDuration);
    eD2States eStateCheck = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, STATE_inferno);
    if (eStateCheck != STATE_none) {
      return 1;
    }

    D2Common::DATATBLS::ItemStats::SetState(pUnit, STATE_inferno, 1);
    return 1;
}

static void __stdcall SKILLASSN_GetTrapHealthBonus(eD2Skills eSkill, D2UnitStrc * pUnit, int32_t nSkillLvl, D2UnitStrc * pMissileUnit) {
    if ((int)eSkill < 0 || (int)eSkill >= sgptDataTable->nTxtSkillsCount || !(sgptDataTable->pTxtSkills + eSkill)) {
      return;
    }
    if (!pMissileUnit) {
      return;
    }

    int nLifetime = pMissileUnit->nClassId;
    if (!(nLifetime >= 0 && nLifetime < sgptDataTable->nTxtMissilesSize)) {
      return;
    }

    D2MissilesTxt* pMissileTxt = sgptDataTable->pTxtMissiles + nLifetime;
    if (!pMissileTxt) {
      return;
    }

    nLifetime = D2Common::Skills::D2GetSkillCalc(pUnit, sgptDataTable->pTxtSkills[eSkill].calc[0], eSkill, nSkillLvl);
    if (nLifetime <= 0) {
      nLifetime = pMissileTxt->Param2 - 1 + nSkillLvl;
    }
    if (nLifetime > 1) {
      if (nLifetime >= 0xff) {
        nLifetime = 0xff;
      }
    } else {
      nLifetime = 1;
    }

    D2Common::PATH::DynamicPath::OverwriteDistanceAndMaxDistance(pMissileUnit->pPath.pDynamicPath, (uint8_t)nLifetime);
    D2Common::Units::SetAnimationSpeed(pMissileUnit, (int32_t)((int64_t)((uint64_t)(uint8_t)pMissileTxt->AnimLen << 8) / (int64_t)nLifetime));
    D2Common::Units::Missile::SetTotalFrames(pMissileUnit, nLifetime);
    D2Common::Units::Missile::SetCurrentFrame(pMissileUnit, nLifetime);
}

static int SKILLMONST_TriggerModeChange(D2UnitStrc * pUnit, ::SGAMEDATA * pGame) {
    uint32_t nEventDelay = 0xb;
    if (pUnit && pUnit->eUnitType == UNIT_MONSTER) {
      int nMonStatsExIdx;
      nMonStatsExIdx = pUnit->nClassId;
      if (nMonStatsExIdx >= 0 && nMonStatsExIdx < sgptDataTable->nTxtMonStatsSize) {
        nMonStatsExIdx = (int)sgptDataTable->pTxtMonStats[nMonStatsExIdx].MonStatsEx;
        D2MonStats2Txt* pMonStatsExTxt = nMonStatsExIdx >= 0 && nMonStatsExIdx < sgptDataTable->nTxtMonStatsExSize ? sgptDataTable->pTxtMonStatsEx + nMonStatsExIdx : nullptr;
        if (pMonStatsExTxt) {
          nEventDelay = (uint32_t)pMonStatsExTxt->byInfernoLen;
        }
      }
    }

    GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit, UNITEVENTCALLBACK_MODECHANGE, 0);
    GAME::Event::SetEvent(pGame, pUnit, 1, pGame->dwGameFrame + nEventDelay, 0, 0);
    return 1;
}

void __fastcall SKILLASSN_GetShadowHealthBonus(D2SkillsTxt * pSkillsTxt, D2UnitStrc * pUnit) {
    D2MonStats2Txt* pMonStatsEx;
    if (pUnit && pUnit->eUnitType == UNIT_MONSTER) {
      int nMonStats2Idx;
      nMonStats2Idx = pUnit->nClassId;
      if (!(nMonStats2Idx >= 0 && nMonStats2Idx < sgptDataTable->nTxtMonStatsSize)) {
        return;
      }

      nMonStats2Idx = (int)sgptDataTable->pTxtMonStats[nMonStats2Idx].MonStatsEx;
      if (!(nMonStats2Idx >= 0 && nMonStats2Idx < sgptDataTable->nTxtMonStatsExSize)) {
        return;
      }

      pMonStatsEx = sgptDataTable->pTxtMonStatsEx + nMonStats2Idx;
      if (!pMonStatsEx) {
        return;
      }
      if (pSkillsTxt->monanim == '\x0e') {
        D2Common::Units::SetSequenceFrame(pUnit, (uint8_t)pMonStatsEx->byInfernoAnim - 1);
        pUnit->nFrameCount = ((uint8_t)pMonStatsEx->byInfernoAnim + 1) * 0x100;
        return;
      }

      pUnit->nGfxCurrentFrame = (uint32_t)(uint8_t)pMonStatsEx->byInfernoAnim << 8;
      return;
    }

    D2Common::Units::SetSequenceFrame(pUnit, 8);
    pUnit->nFrameCount = 0x500;
}

// SrvDoFunc #95: server-side trap/sentry skill handler that spawns one missile from the caster unit toward the target cursor. Looks up srvmissilea from the skill's txt row, computes velocity from VelLev×level/8+Vel, builds a D2SkillArgStrc, and calls CreatingMissile. On success, applies trap health bonuses, checks the inferno state to optionally reschedule the next fire frame via SetEvent, otherwise triggers a mode-change. Returns 0 if the skill, missile id, or target position is invalid.
BOOL __fastcall Skills_SrvDoFunc_095_SpawnTrapMissile(::SGAMEDATA * pGame, D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    int32_t nNextFireFrame;
    eD2States eStateCheck;
    int32_t dwTmp;
    D2SkillArgStrc sSkillArg;
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillsTxt = sgptDataTable->pTxtSkills + eSkill;
    if (!pSkillsTxt) {
      return 0;
    }

    D2SkillStrc* pSkill = D2Common::Units::GetCurrentSkill(pUnit);
    if (!pSkill) {
      return 0;
    }

    eMissilesId nMissileId = (eMissilesId)pSkillsTxt->srvmissile[1];
    if (!((int)nMissileId >= 0 && (int)nMissileId < sgptDataTable->nTxtMissilesSize)) {
      return 0;
    }

    D2MissilesTxt* pMissileTxt = D2Client::GetMissleById(nMissileId);
    memset(&sSkillArg, 0, 0x5c);
    sSkillArg.nFlags = 0x25;
    sSkillArg.pOwner = pUnit;
    sSkillArg.nX = D2Client::Units::GetXPosFromDynamicPathUnit(pUnit);
    sSkillArg.nY = D2Client::Units::GetYPosFromDynamicPathUnit(pUnit);
    sSkillArg.nSkillLevel = nSkillLvl;
    int nVelCalc = (uint32_t)(uint8_t)pMissileTxt->VelLev * nSkillLvl;
    sSkillArg.nVelocityOverride = nVelCalc / 8 + (uint32_t)pMissileTxt->Vel;
    sSkillArg.nMissileTxtNo = nMissileId;
    BOOL BVar1 = SkillsServer::SKILLS_GetTargetOrCursorPos(pGame, pUnit, (uint32_t*)&sSkillArg.nUnitX, (uint32_t*)&sSkillArg.nUnitY);
    if (BVar1) {
      D2UnitStrc* pMissileUnit;
      pMissileUnit = MISSILES::Missiles::CreatingMissile(pGame, &sSkillArg);
      if (pMissileUnit) {
        SKILLASSN_GetTrapHealthBonus(eSkill, pUnit, nSkillLvl, pMissileUnit);
        SKILLASSN_GetShadowHealthBonus(pSkillsTxt, pUnit);
        nNextFireFrame = D2Common::Skills::SKILL_GetParam1(pSkill);
        if (pGame->dwGameFrame < nNextFireFrame) {
          eStateCheck = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, STATE_inferno);
          if (eStateCheck != STATE_none) {
            nNextFireFrame = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillsTxt->calc[2], eSkill, nSkillLvl);
            if (nNextFireFrame < 1) {
              nNextFireFrame = 1;
            }

            GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit, UNITEVENTCALLBACK_ENDANIM, 0);
            GAME::Event::EVENT_RemoveUnitTimersByType(pGame, pUnit, UNITEVENTCALLBACK_MODECHANGE, 0);
            GAME::Event::SetEvent(pGame, pUnit, 0, pGame->dwGameFrame + nNextFireFrame, 0, 0);
            return 1;
          }
        }

        SKILLMONST_TriggerModeChange(pUnit, pGame);
        return 1;
      }
    }

    SKILLMONST_TriggerModeChange(pUnit, pGame);
    return 0;
}

